def normalize(text):
    return "".join(str(text).split()).lower()


def status_class(status):
    if status in ("출고 완료", "정상"):
        return "status-done"
    if status in ("검수 중", "출고 준비"):
        return "status-live"
    if status == "확인 필요":
        return "status-error"
    return "status-wait"


def set_job(job_id):
    st.session_state.selected_job = job_id


def set_all_materials(job_id, value):
    for material in jobs[job_id]["자재 목록"]:
        code = material["자재 코드"]
        st.session_state.selected_materials[code] = value
        # 이미 화면에 만들어진 체크박스도 다음 실행 때 같은 상태를 유지합니다.
        st.session_state[f"pick_{code}"] = value


def order_counts():
    return Counter(order["상태"] for order in st.session_state.orders)


def advance_order(order, scenario):
    if order["상태"] == "확인 필요":
        if scenario == "정상":
            order["단계"] = 4
            order["상태"] = "출고 완료"
            order["검수"] = "정상"
        return
    if order["단계"] >= 4:
        return
    if order["단계"] == 3 and scenario != "정상":
        order["상태"] = "확인 필요"
        order["검수"] = scenario
        return
    order["단계"] += 1
    labels = ["신청 접수", "출고 준비", "컨베이어 이송", "검수 중", "출고 완료"]
    order["상태"] = labels[order["단계"]]
    order["검수"] = "정상" if order["단계"] == 4 else ("검수 대기" if order["단계"] == 3 else order["검수"])


def selected_order_object():
    for order in st.session_state.orders:
        if order["신청번호"] == st.session_state.selected_order:
            return order
    return st.session_state.orders[0] if st.session_state.orders else None

